 height="14" rx="2"/><path d="m3 6 9 7 9-7"/></>,arrowRight:<path d="M4 12h16m-6-6 6 6-6 6"/>,file:<><path d="M14 3H5v18h14V8Zm0 0v5h5M8 12h8m-8 4h6"/></>,truck:<><path d="M3 5h11v12H3Zm11 5h4l3 4v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/></>,
