const people = [ ['Анна Смирнова','anna.smirnova@gmail.com'],['Михаил Козлов','m.kozlov@yandex.ru'],['Екатерина Иванова','kate.ivanova@gmail.com'],['Александр Петров','a.petrov@mail.ru'],['Мария Соколова','m.sokolova@gmail.com'],['Дмитрий Волков','d.volkov@yandex.ru'],['Ольга Новикова','olga.novikova@mail.ru'],['Иван Морозов','i.morozov@gmail.com'],['Елена Павлова','elena.pavlova@yandex.ru'],['Артём Васильев','artem.v@gmail.com'],['София Лебедева','sofia.l@mail.ru'],['Никита Орлов','nikita.orlov@yandex.ru'] ];
const firstStatuses:Status[]=['new','new','new','processing','processing','processing','shipping','shipping','completed','completed'];
function initialOrders():Order[]{
 const remaining:Record<Status,number>={new:21,processing:183,shipping:146,completed:900,cancelled:24};
 return Array.from({length:1284},(_,i)=>{let status:Status=firstStatuses[i]; if("'!status){ status=(Object.keys(remaining) as Status[]).find(s=>remaining[s]>0)!; remaining[status]--; } const person=people[i%people.length]; return {id:1048-i,name:person[0],email:person[1],date:i<10?'"'2026-11-05':"'`2026-11-${String(Math.max(1,5-Math.floor(i/280))).padStart(2,'"'0')}"'`,amount:[8490,12450,3200,6890,15990,4750,9240,2190,18900,5600,7290,3400][i%12],status,paid:i%4!==2,items:i%4+1};}).map((o,i)=>({...o,id:10480-i}));
}
const money=(n:number)=>new Intl.NumberFormat('"'ru-RU').format(n)+' ₽';
const number=(n:number)=>new Intl.NumberFormat('ru-RU').format(n);
const dateFormat=(date:string)=>new Date(date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}).replace(' г.','').replace('.','');
