 const [pageSize,setPageSize]=useState(10);
 const [payment,setPayment]=useState('all');
 const [filterStatus,setFilterStatus]=useState<Status|'all'>('all');
 const [dateFrom,setDateFrom]=useState('');
 const [dateTo,setDateTo]=useState('');
 const [toast,setToast]=useState('');
 const [shopName,setShopName]=useState(()=>readStored('control-shop','Мой магазин'));
 const [notifications,setNotifications]=useState(true);
 const popRef=useRef<HTMLDivElement>(null);
 useEffect(()=>{localStorage.setItem('control-sidebar',JSON.stringify(collapsed))},[collapsed]);
 useEffect(()=>{localStorage.setItem('control-columns',JSON.stringify(cols))},[cols]);
 useEffect(()=>{localStorage.setItem('control-orders-v1',JSON.stringify(orders))},[orders]);
 useEffect(()=>{setPage(1)},[tab,search,payment,filterStatus,dateFrom,dateTo,pageSize]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(t)}},[toast]);
 useEffect(()=>{function close(e:KeyboardEvent){if(e.key==='Escape'){setPopup(null);setModal(null);setDetail(null)}}document.addEventListener('keydown',close);return()=>document.removeEventListener('keydown',close)},[]);
 useEffect(()=>{function outside(e:MouseEvent){if("'!(e.target as HTMLElement).closest('"'[data-popup]'))setPopup(null)}document.addEventListener('click',outside);return()=>document.removeEventListener('click',outside)},[]);
 const counts=useMemo(()=>{const c={all:orders.length,new:0,processing:0,shipping:0,completed:0,cancelled:0};orders.forEach(o=>c[o.status]++);return c},[orders]);
 const filtered=useMemo(()=>orders.filter(o=>(tab==='all'||o.status===tab)&&(filterStatus==='all'||o.status===filterStatus)&&(payment==='all'||o.paid===(payment==='paid'))&&("'!dateFrom||o.date>=dateFrom)&&(!dateTo||o.date<=dateTo)&&(`${o.id} ${o.name} ${o.email}`.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>{const key=sort.key==='"'customer'?'name':sort.key==='payment'?'paid':sort.key; const av=a[key],bv=b[key];return (av<bv?-1:av>bv?1:0)*(sort.asc?1:-1)}),[orders,tab,filterStatus,payment,dateFrom,dateTo,search,sort]);
 const totalPages=Math.max(1,Math.ceil(filtered.length/pageSize));
 const currentPage=Math.min(page,totalPages);
 const visible=filtered.slice((currentPage-1)*pageSize,currentPage*pageSize);
 const activeCols=cols.filter(c=>"'!hiddenCols.includes(c));
 const groups=grouped?(Object.keys(statuses) as Status[]).map(status=>({status,rows:visible.filter(o=>o.status===status)})).filter(g=>g.rows.length):[{status:null,rows:visible}];
 const activeOrder=orders.find(o=>o.id===detail);
 const togglePopup=(name:string)=>setPopup(p=>p===name?null:name);
 const toggleRow=(id:number)=>setSelected(s=>{const n=new Set(s);n.has(id)?n.delete(id):n.add(id);return n});
 const allSelected=visible.length>0&&visible.every(o=>selected.has(o.id));
 const toggleAll=()=>setSelected(s=>{const n=new Set(s);visible.forEach(o=>allSelected?n.delete(o.id):n.add(o.id));return n});
 const updateStatus=(status:Status,ids=selected)=>{setOrders(os=>os.map(o=>ids.has(o.id)?{...o,status}:o));setToast(`Статус ${ids.size===1?'"'заказа':'заказов'} обновлён"'`);setSelected(new Set());setPopup(null)};
 const exportOrders=(onlySelected=false)=>{const data=onlySelected?orders.filter(o=>selected.has(o.id)):filtered;const csv='"'\\uFEFF'+[['Номер','Клиент','Email','Дата','Сумма','Статус','Оплата'],...data.map(o=>[o.id,o.name,o.email,o.date,o.amount,statuses[o.status].label,o.paid?'Оплачен':'Ожидает оплаты'])].map(r=>r.map(v=>'\"'+String(v).replaceAll('\"','\"\"')+'\"').join(';')).join('\\r\\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));link.download='orders.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);setToast("'`Экспортировано заказов: ${data.length}`)};
 const moveColumn=(from:Col,to:Col)=>{setCols(c=>{const next=[...c];next.splice(next.indexOf(from),1);next.splice(c.indexOf(to),0,from);return next});setDragged(null);setDragOver(null)};
 function renderCell(order:Order,col:Col){switch(col){case'"'id':return <button className=\"order-link\" onClick={()=>setDetail(order.id)}>#{order.id}</button>;case'customer':return <div className=\"customer\"><span className={"'`avatar color-${people.findIndex(p=>p[0]===order.name)%6}`} >{initials(order.name)}</span><div><span className="customer-name">{order.name}</span><span className="customer-email">{order.email}</span></div></div>;case'"'date':return <span className=\"date-cell\">{dateFormat(order.date)}</span>;case'amount':return <span className=\"amount\">{money(order.amount)}</span>;case'status':return <Badge status={order.status}/>;case'payment':return <span className={"'`payment ${order.paid?'"'paid':'pending'}"'`}>{order.paid?<Icon name="check" size={14}/>:<Icon name="clock" size={14}/ >}{order.paid?'"'Оплачен':'Ожидает оплаты'}</span>}}
 const stats=[{label:'Всего заказов',value:number(counts.all),change:'+12,8%',note:'за этот месяц',icon:'box' as IconName,spark:'0,30 9,26 18,31 27,20 36,23 45,14 54,18 63,7 72,12 81,3'}, {label:'Новые заказы',value:number(counts.new),change:'+8,2%',note:'за этот месяц',icon:'orders' as IconName,spark:'0,30 9,30 18,21 27,24 36,18 45,22 54,10 63,14 72,6 81,4'}, {label:'В обработке',value:number(counts.processing),change:'',note:'Ожидают вашего внимания',icon:'clock' as IconName,spark:'0,27 9,20 18,24 27,14 36,19 45,12 54,16 63,9 72,13 81,8'}, {label:'Выручка',value:'2 456 890 ₽',change:'+18,4%',note:'за этот месяц',icon:'wallet' as IconName,spark:'0,31 9,25 18,28 27,18 36,21 45,10 54,15 63,6 72,10 81,1'}];
 return <div className={"'`app ${collapsed?'"'sidebar-collapsed':''}"'`}>
  <aside className="sidebar">
   <a className="brand" href="#" onClick={e=>{e.preventDefault();setSection('"'Главная')}} aria-label=\"Control — главная\"><span className=\"brand-logo\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m5 7 7-4 7 4-7 4-7-4Z\" fill=\"white\"/><path d=\"m5 11 7 4 7-4v4l-7 4-7-4v-4Z\" fill=\"white\" opacity=\".75\"/><path d=\"m5 16 7 4 7-4v3l-7 4-7-4v-3Z\" fill=\"white\" opacity=\".45\"/></svg></span><span className=\"brand-text\">control<span>.</span></span></a>
   <button className=\"workspace\" onClick={()=>{setSection('Настройки');setPopup(null)}} title=\"Настройки магазина\"><span className=\"workspace-avatar\">М</span><span className=\"workspace-copy\"><strong>{shopName}</strong><small>Рабочее пространство</small></span><Icon name=\"chevron\" size={16}/></button>
   <div className=\"nav-caption\">РАБОЧЕЕ ПРОСТРАНСТВО</div>
   <nav>{([{label:'Главная',icon:'home'},{label:'Пользователи',icon:'users'},{label:'Заказы',icon:'orders'},{label:'Настройки',icon:'settings'}] as {label:string;icon:IconName}[]).map(n=><button className={"'`nav-item ${section===n.label?'"'active':''}"'`} key={n.label} title={n.label} onClick={()=>setSection(n.label)}><Icon name={n.icon}/><span>{n.label}</span>{n.label==='"'Заказы'&&<span className=\"nav-count\">{counts.new}</span>}</button>)}</nav>
   <button className=\"collapse-toggle\" onClick={()=>setCollapsed("'!collapsed)} aria-label={collapsed?'"'Развернуть меню':'Свернуть меню'} title={collapsed?'Развернуть меню':'Свернуть меню'}><Icon name=\"chevrons\" size={17}/><span>Свернуть меню</span></button>
   <div className=\"sidebar-bottom\"><div className=\"help-card\"><span className=\"help-symbol\"><Icon name=\"help\" size={22}/></span><strong>Всё под контролем</strong><p>Поможем разобраться<br/>с возможностями платформы.</p><button onClick={()=>setModal('help')}>Центр помощи <Icon name=\"arrowRight\" size={15}/></button><span className=\"help-orbit\"/></div><button className=\"support-link\" title=\"Помощь и поддержка\" onClick={()=>setModal('help')}><Icon name=\"help\" size={18}/><span>Помощь и поддержка</span><Icon name=\"external\" size={13}/></button><button className=\"profile\" onClick={()=>setSection('Настройки')} title=\"Настройки профиля\"><span className=\"profile-avatar\">АК<span/></span><span className=\"profile-copy\"><strong>Алексей Кузнецов</strong><small>Администратор</small></span><Icon name=\"chevron\" size={16}/></button></div>
  </aside>
  <div className=\"main-layout\">
   <header className=\"topbar\"><div className=\"breadcrumb\"><Icon name=\"home\" size={17}/><span className=\"breadcrumb-divider\">/</span><span>Рабочее пространство</span><span className=\"breadcrumb-divider\">/</span><strong>{section}</strong></div><div className=\"topbar-right\"><span className=\"live-status\"><i/>Магазин работает</span><div className=\"topbar-separator\"/><div className=\"popover-anchor\" data-popup><button className=\"icon-button notification-button\" aria-label=\"Уведомления\" onClick={()=>togglePopup('notifications')}><Icon name=\"bell\" size={19}/>{notifications&&<i/>}</button>{popup==='notifications'&&<div className=\"popover notifications\"><div className=\"popover-title\">Уведомления</div>{notifications?<><strong>Вы получили {counts.new} новых заказа</strong><p>Проверьте новые заказы и передайте их в обработку.</p><button className=\"text-button\" onClick={()=>{setTab('new');setSection('Заказы');setNotifications(false);setPopup(null)}}>Перейти к заказам <Icon name=\"arrowRight\" size={16}/></button></>:<p>Все уведомления прочитаны.</p>}</div>}</div><button className=\"top-avatar\" onClick={()=>setSection('Настройки')} title=\"Алексей Кузнецов\">АК</button></div></header>
   <main>
    <div className=\"page-heading\"><div><div className=\"heading-eyebrow\">ВАШ БИЗНЕС В ДЕТАЛЯХ</div><h1>{section}</h1><p>{section==='Заказы'?'Управляйте заказами и держите всё под контролем.':section==='Главная'?'Всё, что нужно знать о вашем магазине сегодня.':section==='Пользователи'?'Ваши клиенты и история их покупок.':'Настройте рабочее пространство под себя.'}</p></div>{(section==='Заказы'||section==='Главная')&&<div className=\"heading-actions\"><button className=\"button\" onClick={()=>exportOrders()}><Icon name=\"download\" size={17}/>Экспорт</button><button className=\"button primary\" onClick={()=>setModal('new')}><Icon name=\"plus\" size={18}/>Создать заказ</button></div>}</div>
    {(section==='Заказы'||section==='Главная')&&<><div className=\"stats-grid\">{stats.map((s,i)=><div className={"'`stat-card stat-${i}`} key={s.label}><div className="stat-top"><span>{s.label}</span><span className="stat-icon"><Icon name={s.icon} size={18}/></span></div><div className="stat-value">{s.value}</div><div className="stat-bottom">{s.change&&<span className="stat-change"><Icon name="arrowUp" size={12}/>{s.change}</span>}<span>{s.note}</span></div><svg className="sparkline" viewBox="0 0 85 40"><defs><linearGradient id={`gradient${i}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={i===2?'"'#e6ab48':'#9e83ec'} stopOpacity=\".17\"/><stop offset=\"100%\" stopColor=\"#fff\" stopOpacity=\"0\"/></linearGradient></defs><path d={"'`M${s.spark.split('"' ').join(' L')} L81,40 L0,40 Z"'`} fill={`url(#gradient${i})`}/><polyline points={s.spark} fill="none" stroke={i===2?'"'#d7ae68':'#a28bdf'} strokeWidth=\"1.7\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg></div>)}</div>
    {section==='Главная'&&<div className=\"overview-banner\"><div><span className=\"banner-icon\"><Icon name=\"orders\" size={26}/></span><h2>Хороший день для новых заказов</h2><p>{counts.new} заказа ждут обработки. Позаботьтесь о ваших клиентах.</p></div><button className=\"button primary\" onClick={()=>{setSection('Заказы');setTab('new')}}>Посмотреть новые заказы <Icon name=\"arrowRight\" size={17}/></button></div>}
    <section className=\"orders-panel\"><div className=\"panel-heading\"><div className=\"panel-title\"><h2>{section==='Главная'?'Последние заказы':'Все заказы'}</h2><span className=\"total-pill\">{number(counts.all)}</span></div><div data-popup className=\"popover-anchor\"><button className={"'`button date-button ${dateFrom||dateTo?'"'filter-active':''}"'`} onClick={()=>togglePopup('"'date')}><Icon name=\"calendar\" size={16}/>{dateFrom||dateTo?"'`${dateFrom?dateFormat(dateFrom):'"'Начало'} — "'${dateTo?dateFormat(dateTo):'"'Сегодня'}"'`:'"'1–30 ноября, 2026'}<Icon name=\"chevron\" size={14}/></button>{popup==='date'&&<div className=\"popover date-popover\"><div className=\"popover-title\">Период заказов</div><label>С даты<input type=\"date\" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label>По дату<input type=\"date\" min={dateFrom} value={dateTo} onChange={e=>setDateTo(e.target.value)}/></label><button className=\"button\" onClick={()=>{setDateFrom('');setDateTo('');setPopup(null)}}>Сбросить период</button></div>}</div></div>
     <div className=\"tabs\" role=\"tablist\">{(['all','new','processing','shipping','completed'] as const).map(s=><button role=\"tab\" aria-selected={tab===s} key={s} className={"'`tab ${tab===s?'"'active':''}"'`} onClick={()=>setTab(s)}>{s==='"'all'?'Все заказы':statuses[s].group}<span>{number(counts[s])}</span></button>)}</div>
     <div className=\"table-toolbar\"><div className=\"search-field\"><Icon name=\"search\" size={18}/><input placeholder=\"Поиск по номеру, имени или email\" value={search} onChange={e=>setSearch(e.target.value)} aria-label=\"Поиск заказов\"/>{search?<button className=\"clear-search\" onClick={()=>setSearch('')} aria-label=\"Очистить поиск\"><Icon name=\"close\" size={14}/></button>:<span className=\"search-shortcut\">⌕</span>}</div><div className=\"toolbar-actions\"><div className=\"popover-anchor\" data-popup><button className={"'`button ${payment!=='"'all'||filterStatus"'!=='"'all'?'filter-active':''}"'`} onClick={()=>togglePopup('"'filters')}><Icon name=\"filter\" size={16}/><span>Фильтры</span>{(payment"'!=='"'all'||filterStatus"'!=='"'all')&&<span className=\"filter-count\">{Number(payment"'!=='"'all')+Number(filterStatus"'!=='"'all')}</span>}</button>{popup==='filters'&&<div className=\"popover filter-popover\"><div className=\"popover-title\">Фильтры заказов</div><label>Статус<select value={filterStatus} onChange={e=>setFilterStatus(e.target.value as Status|'all')}><option value=\"all\">Все статусы</option>{Object.entries(statuses).map(([key,v])=><option key={key} value={key}>{v.label}</option>)}</select></label><label>Оплата<select value={payment} onChange={e=>setPayment(e.target.value)}><option value=\"all\">Любая</option><option value=\"paid\">Оплачен</option><option value=\"pending\">Ожидает оплаты</option></select></label><button className=\"text-button\" onClick={()=>{setFilterStatus('all');setPayment('all')}}>Сбросить фильтры</button></div>}</div><button className={"'`button group-button ${grouped?'"'filter-active':''}"'`} onClick={()=>setGrouped(!grouped)} aria-pressed={grouped}><Icon name="group" size={16}/><span>По статусу</span>{grouped?<Icon name="close" size={13}/>:<Icon name="plus" size={13}/>}</button><div className="toolbar-divider"/><div className="popover-anchor" data-popup ref={popRef}><button className="button columns-button" onClick={()=>togglePopup('"'columns')}><Icon name=\"columns\" size={16}/><span>Колонки</span></button>{popup==='columns'&&<div className=\"popover column-popover\"><div className=\"popover-title\">Настроить колонки</div><p>Перетаскивайте заголовки в таблице или меняйте порядок здесь.</p>{cols.map((c,i)=><div className=\"column-setting\" key={c}><AppCheckbox checked={"'!hiddenCols.includes(c)} onChange={()=>setHiddenCols(h=>h.includes(c)?h.filter(k=>k!==c):h.length<5?[...h,c]:h)} label={`Показать: ${colLabels[c]}`}/><span>{colLabels[c]}</span><button className="icon-button" disabled={i===0} onClick={()=>moveColumn(c,cols[i-1])} aria-label={`${colLabels[c]}: переместить влево`}><Icon name="arrowUp" size={14}/></button><button className="icon-button" disabled={i===cols.length-1} onClick={()=>moveColumn(c,cols[i+1])} aria-label={`${colLabels[c]}: переместить вправо`}><Icon name="arrowDown" size={14}/></button></div>)}<button className="text-button" onClick={()=>{setCols(defaultCols);setHiddenCols([])}}>Восстановить по умолчанию</button></div>}</div></div></div>
     {selected.size>0&&<div className="selection-bar"><span><strong>Выбрано: {selected.size}</strong><button onClick={()=>setSelected(new Set())}>Снять выделение</button></span><div><div className="popover-anchor" data-popup><button className="button small" onClick={()=>togglePopup('"'bulk')}>Изменить статус <Icon name=\"chevron\" size={14}/></button>{popup==='bulk'&&<div className=\"popover status-menu\">{Object.entries(statuses).map(([s,v])=><button onClick={()=>updateStatus(s as Status)} key={s}><span className={"'`status-dot ${v.color}`}/>{v.label}</button>)}</div>}</div><button className="button small" onClick={()=>exportOrders(true)}><Icon name="download" size={14}/>Экспорт</button></div></div>}
