const firstStatuses:Status[]=['new','new','new','processing','processing','processing','shipping','shipping','completed','completed'];
function initialOrders():Order[]{
 const remaining:Record<Status,number>={new:21,processing:183,shipping:146,completed:900,cancelled:24};
 return Array.from({length:1284},(_,i)=>{let status:Status=firstStatuses[i]; if("'!status){ status=(Object.keys(remaining) as Status[]).find(s=>remaining[s]>0)!; remaining[status]--; } const person=people[i%people.length]; return {id:1048-i,name:person[0],email:person[1],date:i<10?'"'2026-11-05':"'`2026-11-${String(Math.max(1,5-Math.floor(i/280))).padStart(2,'"'0')}"'`,amount:[8490,12450,3200,6890,15990,4750,9240,2190,18900,5600,7290,3400][i%12],status,paid:i%4!==2,items:i%4+1};}).map((o,i)=>({...o,id:10480-i}));
