function readStored<T,>(key:string,fallback:T):T {try {return JSON.parse(localStorage.getItem(key)||'null')??fallback;}catch{return fallback;}}
function Badge({status}:{status:Status}){return <span className={"'`badge ${statuses[status].color}`}><span className="status-dot"/>{statuses[status].label}</span>}
function AppCheckbox({checked,onChange,label,indeterminate=false}:{checked:boolean;onChange:()=>void;label:string;indeterminate?:boolean}){const ref=useRef<HTMLInputElement>(null);useEffect(()=>{if(ref.current)ref.current.indeterminate=indeterminate},[indeterminate]);return <input ref={ref} className="checkbox" type="checkbox" checked={checked} onChange={onChange} aria-label={label}/>}

