/bin/bash -lc "mkdir -p __agent_eval__ && cat > __agent_eval__/dashboard.mjs <<'EOF'
import {chromium} from '@playwright/test';
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:1440,height:1050},deviceScaleFactor:1});
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:5176',{waitUntil:'networkidle'});
await page.screenshot({path:'__agent_eval__/desktop.png',fullPage:true});
const assert=(condition,message)=>{if("'!condition)throw new Error(message);console.log('"'PASS',message)};
assert(await page.locator('.orders-table tbody tr:not(.group-row)').count()===10,'Ten initial orders');
await page.getByRole('checkbox',{name:'Выделить все заказы на странице'}).check();
assert((await page.locator('.selection-bar').innerText()).includes('Выбрано: 10'),'Select all orders');
await page.getByRole('button',{name:'Снять выделение'}).click();
await page.getByRole('checkbox',{name:'Выделить заказ 10480',exact:true}).check();
await page.getByRole('button',{name:'Изменить статус'}).click();
await page.locator('.status-menu').getByRole('button',{name:'В обработке'}).click();
assert(await page.getByRole('button',{name:'#10480',exact:true}).locator('xpath=ancestor::tr').getByText('В обработке',{exact:true}).count()===1,'Bulk status update');
await page.getByRole('textbox',{name:'Поиск заказов'}).fill('anna.smirnova');
assert(await page.locator('.orders-table .customer-name').first().innerText()==='Анна Смирнова','Customer search');
